<script setup lang="ts">
import type { CommunityRecord } from '~/types/community'
import type { PointDto, PageDto, InspectionDto } from '~/types/api'
import { errorMessage, todayLocal } from '~/utils/format'
interface PlanData { inspector: string; from: string; to: string; typeId: string; pointIds: string[]; notes: string }
const plans=ref<CommunityRecord<PlanData>[]>([]), points=ref<PointDto[]>([]), types=ref<CommunityRecord[]>([]), inspections=ref<InspectionDto[]>([])
const error=ref(''), busy=ref(false), open=ref(false), name=ref(''), search=ref(''), selected=ref('')
const defaults=():PlanData=>({inspector:'',from:todayLocal(),to:todayLocal(),typeId:'',pointIds:[],notes:''})
const form=reactive(defaults())
const typeOptions=computed(()=>types.value.map(x=>({label:x.name,value:x.id})))
const choices=computed(()=>points.value.filter(x=>!search.value||x.name.includes(search.value)||x.address.includes(search.value)))
function completed(plan:CommunityRecord<PlanData>,id:string){return inspections.value.some(x=>x.pointId===id&&x.result!=='incomplete'&&x.date>=plan.data.from&&x.date<=plan.data.to&&(!plan.data.typeId||x.inspectionTypeId===plan.data.typeId))}
async function load(){error.value='';try{plans.value=await $fetch('/api/records/plan');types.value=await $fetch('/api/records/inspection-type');const allPoints:PointDto[]=[];for(let page=1;;page++){const r=await $fetch<PageDto<PointDto>>('/api/points',{query:{page,pageSize:200}});allPoints.push(...r.items);if(page*r.pageSize>=r.total)break}points.value=allPoints;const allInspections:InspectionDto[]=[];for(let page=1;;page++){const r=await $fetch<PageDto<InspectionDto>>('/api/inspections',{query:{page,pageSize:200}});allInspections.push(...r.items);if(page*r.pageSize>=r.total)break}inspections.value=allInspections}catch(e){error.value=errorMessage(e)}}
async function save(){if(!name.value.trim()||!form.inspector.trim()||!form.typeId||!form.pointIds.length){error.value='请填写名称、人员、检查类型并选择场所';return}if(form.to<form.from){error.value='结束日期不能早于开始日期';return}busy.value=true;error.value='';try{await $fetch('/api/records/plan',{method:'POST',body:{name:name.value,parentId:'',data:form},retry:0});open.value=false;await load()}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
onMounted(load)
</script>
<template><div class="page-stack"><PageHeader title="检查安排" back="/"><UButton label="新增安排" icon="i-lucide-plus" @click="name='';Object.assign(form,defaults());open=true" /></PageHeader><UAlert v-if="error" :description="error" color="error" />
  <section v-for="plan in plans" :key="plan.id" class="panel"><button class="panel-body w-full text-left" @click="selected=selected===plan.id?'':plan.id"><div class="flex justify-between gap-2"><strong>{{plan.name}}</strong><span>已查 {{plan.data.pointIds.filter(id=>completed(plan,id)).length}} / {{plan.data.pointIds.length}}</span></div><p class="mt-2 text-muted text-sm">{{plan.data.inspector}} · {{plan.data.from}} 至 {{plan.data.to}}</p></button><div v-if="selected===plan.id"><div v-for="id in plan.data.pointIds" :key="id" class="list-row"><div class="row-body"><strong>{{points.find(x=>x.id===id)?.name??'已停用场所'}}</strong></div><UBadge v-if="completed(plan,id)" label="已检查" variant="subtle" /><UButton v-else label="登记检查" :to="{path:'/inspections/new',query:{pointId:id,typeId:plan.data.typeId,inspector:plan.data.inspector}}" variant="outline" /></div></div></section>
  <EmptyState v-if="!plans.length" title="暂无检查安排" />
  <USlideover v-model:open="open" title="新增检查安排" :dismissible="!busy" :ui="{content:'w-full max-w-[600px]'}"><template #body><div class="space-y-4"><UAlert v-if="error" :description="error" color="error" /><UFormField label="名称" required><UInput v-model="name" class="w-full" /></UFormField><div class="field-grid"><UFormField label="检查人员" required><UInput v-model="form.inspector" class="w-full" /></UFormField><UFormField label="检查类型" required><USelect v-model="form.typeId" :items="typeOptions" class="w-full" /></UFormField><UFormField label="开始日期"><UInput v-model="form.from" type="date" class="w-full" /></UFormField><UFormField label="完成期限"><UInput v-model="form.to" type="date" class="w-full" /></UFormField></div><UFormField label="选择场所" required><UInput v-model="search" placeholder="搜索场所" class="w-full mb-3" /><div class="max-h-80 overflow-auto space-y-3"><UCheckbox v-for="point in choices" :key="point.id" :label="point.name" :model-value="form.pointIds.includes(point.id)" @update:model-value="v=>{form.pointIds=v?[...form.pointIds,point.id]:form.pointIds.filter(x=>x!==point.id)}" /></div></UFormField><span class="text-sm text-muted">已选 {{form.pointIds.length}} 处</span></div></template><template #footer><UButton label="保存安排" :loading="busy" @click="save" /></template></USlideover>
</div></template>
